206	func addressesForClaim(pod *corev1.Pod, claim string) (types.StaticAddrsMap, error) {
207		if pod == nil {
208			return nil, nil
209		}
210	
211		raw, found := annotation.Get(pod, annotation.NetworkDriverStaticAddresses)
212		if !found || strings.TrimSpace(raw) == "" {
213			return nil, nil
214		}
215	
216		// claim → request → addresses
217		var prefixes map[string]types.StaticAddrsMap
218		if err := json.Unmarshal([]byte(raw), &prefixes); err != nil {
219			return nil, fmt.Errorf("failed to unmarshal %s annotation on pod %s/%s: %w", annotation.NetworkDriverStaticAddresses, pod.Namespace, pod.Name, err)
220		}
221	
222		return prefixes[claim], nil
223	}
